          "translation": "또 다른 예로, 일부 연구자들은 검색 과정에서 수집된 암묵적 피드백을 기반으로 동적으로 재정렬된 관련 문장 목록을 제공함으로써 사람들이 더 잘 검색하도록 돕고자 했다.",
